// Overlap chunker with page metadata (plain JS, runs anywhere)
function chunkText(text, { size = 500, overlap = 75, source = 'doc', pageOf = null } = {}) {
  const chunks = [];
  let start = 0, i = 0;
  while (start < text.length) {
    let end = Math.min(start + size, text.length);
    if (end < text.length) { // prefer sentence boundary
      const cut = text.lastIndexOf('. ', end);
      if (cut > start + size * 0.5) end = cut + 1;
    }
    chunks.push({ id: `${source}#${i++}`, text: text.slice(start, end).trim(), source, pageOf });
    if (end >= text.length) break;
    start = end - overlap;
  }
  return chunks;
}

// Minimal TF-IDF retrieval over chunks (plain JS — the honest baseline)
function tokenize(s) { return s.toLowerCase().match(/[a-z0-9]+/g) || []; }
function tfidfRetrieve(chunks, query, k = 3) {
  const docs = chunks.map((c) => tokenize(c.text));
  const df = new Map();
  for (const d of docs) for (const t of new Set(d)) df.set(t, (df.get(t) || 0) + 1);
  const N = docs.length;
  const vec = (tokens) => {
    const tf = new Map();
    for (const t of tokens) tf.set(t, (tf.get(t) || 0) + 1);
    const v = new Map();
    for (const [t, f] of tf) v.set(t, f * Math.log(1 + N / (df.get(t) || N)));
    return v;
  };
  const cos = (a, b) => {
    let dot = 0, na = 0, nb = 0;
    for (const [t, x] of a) { na += x * x; if (b.has(t)) dot += x * b.get(t); }
    for (const x of b.values()) nb += x * x;
    return na && nb ? dot / (Math.sqrt(na) * Math.sqrt(nb)) : 0;
  };
  const qv = vec(tokenize(query));
  return chunks
    .map((c, i) => ({ id: c.id, score: cos(qv, vec(docs[i])) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, k);
}

